        "instances_tested": len(n_values),
        "conjecture_holds": support_fraction >= 0.8 and max_T > 0,
        "counterexample": "" if support_fraction >= 0.8 else f"n={len(n_values)}, T={max_T}"
    }

if __name__ == "__main__":
